from pathlib import Path
import re

paths = [Path('/config/defaults.ini'), Path('/config/custom.ini')]
sections = {}
section_order = []
for path in paths:
    current = None
    for raw in path.read_text().splitlines():
        line = raw.strip()
        if not line or line.startswith(('#', ';')):
            continue
        match = re.fullmatch(r'\[([^]]+)\]', line)
        if match:
            current = match.group(1)
            if current not in sections:
                sections[current] = {}
                section_order.append(current)
        elif current is not None and '=' in raw:
            key, value = raw.split('=', 1)
            sections[current][key.strip()] = value.strip()

out = ''.join(f'[{section}]\n' + ''.join(f'{key}={value}\n' for key, value in values.items()) + '\n' for section, values in sections.items())
Path('/config/merged.ini').write_text(out)
print(out, end='')
